/**
 * Accordion. Molded panels that expand. Composes
 * var(--echo-*). Height animates via Base UI's --accordion-panel-height +
 * data-starting/ending-style (CSS transition; Base UI auto-detects it).
 */
/*
 * Ruled rows, not molded bars (2026-09-18). Each header used to be a raised
 * cap with a separate box hung under it, so a three-item accordion was three
 * big buttons. A disclosure list is a LIST: hairlines between rows, the title
 * as text, and the chevron as the one affordance — the same language as the
 * template index.
 */
.echo-accordion {
  display: grid;
  border-bottom: var(--echo-border-hairline, 1px) solid var(--echo-seam);
}

.echo-accordion__item {
  border-top: var(--echo-border-hairline, 1px) solid var(--echo-seam);
}

.echo-accordion__header {
  margin: 0;
}

.echo-accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--echo-space-6);
  width: 100%;
  min-height: var(--echo-control-default);
  padding: var(--echo-space-6) var(--echo-space-3);
  border: 0;
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  text-align: start;
  color: var(--echo-text);
  background: transparent;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-md);
  font-weight: var(--echo-weight-semibold, 600);
  transition: background var(--echo-duration-tick) ease;
}
@media (hover: hover) {
  .echo-accordion__trigger:hover {
    background: color-mix(in oklab, var(--echo-cap) 28%, transparent);
  }
}
.echo-accordion__trigger:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: -2px;
  box-shadow: var(--echo-shadow-ring-inset, inset 0 0 0 2px var(--echo-accent-ink, var(--echo-accent-glow)));
}

.echo-accordion__chevron {
  flex: none;
  color: var(--echo-text-dim);
  /* It flips over on a spring, overshooting a touch past the turn. */
  transition:
    transform var(--echo-duration-pop) var(--echo-ease-pop),
    color var(--echo-duration-tick) ease;
}
/* It notices the pointer: a nudge toward where the panel would go. */
@media (hover: hover) {
  .echo-accordion__trigger:not([data-disabled]):hover .echo-accordion__chevron {
    transform: translateY(2px);
    color: var(--echo-text);
  }
}
.echo-accordion__trigger[data-panel-open] .echo-accordion__chevron {
  transform: rotate(180deg);
  color: var(--echo-text);
}
@media (hover: hover) {
  .echo-accordion__trigger[data-panel-open]:not([data-disabled]):hover .echo-accordion__chevron {
    transform: rotate(180deg) translateY(2px);
  }
}

.echo-accordion__panel {
  overflow: hidden;
  height: var(--accordion-panel-height);
  color: var(--echo-text-dim);
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-body, 1.55);
  /* Apple's sheet curve: quick to open, settling without overshoot — a
     panel that bounced would jolt everything below it. */
  transition: height var(--echo-duration-pop) cubic-bezier(0.32, 0.72, 0, 1);
}
.echo-accordion__panel[data-starting-style],
.echo-accordion__panel[data-ending-style] {
  height: 0;
}
.echo-accordion__panel[data-ending-style] {
  transition-duration: var(--echo-duration-sweep);
}

.echo-accordion__panel-inner {
  padding: 0 var(--echo-space-3) var(--echo-space-8);
  max-width: 62ch;
  /* The contents surface once the panel has opened under them. */
  transition:
    opacity var(--echo-duration-sweep) ease var(--echo-duration-tick),
    transform var(--echo-duration-pop) var(--echo-ease-pop) var(--echo-duration-tick);
}
.echo-accordion__panel[data-starting-style] .echo-accordion__panel-inner,
.echo-accordion__panel[data-ending-style] .echo-accordion__panel-inner {
  opacity: 0;
  transform: translateY(-6px);
}
.echo-accordion__panel[data-ending-style] .echo-accordion__panel-inner {
  transition-duration: var(--echo-duration-tick);
  transition-delay: 0s;
}

@media (prefers-reduced-motion: reduce) {
  .echo-accordion__panel,
  .echo-accordion__panel-inner,
  .echo-accordion__chevron {
    transition: none;
  }
  @media (hover: hover) {
    .echo-accordion__trigger:not([data-disabled]):hover .echo-accordion__chevron {
      transform: none;
    }
    .echo-accordion__trigger[data-panel-open]:not([data-disabled]):hover .echo-accordion__chevron {
      transform: rotate(180deg);
    }
  }
}

"use client";

/**
 * Accordion. Base UI Accordion behavior (keyboard,
 * a11y, panel height measurement) skinned as molded device panels, with a click
 * sound on toggle. Panel height animates via CSS (Base UI auto-detects the
 * transition), so no GSAP presence is needed here.
 *
 * Compound API: <Accordion><Accordion.Item><Accordion.Trigger/><Accordion.Panel/></Accordion.Item></Accordion>.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import type { ComponentProps } from "react";
import { Accordion as BaseAccordion } from "@base-ui/react/accordion";
import { useSoundOptional } from "echo-ui-core/sound";
import "./accordion.css";

const cx = (...c: (string | undefined)[]) => c.filter(Boolean).join(" ");

/** Narrow Base UI's string-or-function className to a plain string for skinning. */
type Skin<T> = Omit<T, "className"> & { className?: string };

function AccordionRoot({
  onValueChange,
  className,
  ...props
}: Skin<ComponentProps<typeof BaseAccordion.Root>>) {
  const sound = useSoundOptional();
  return (
    <BaseAccordion.Root
      className={cx("echo-accordion", className)}
      onValueChange={(value, eventDetails) => {
        sound?.play("tap");
        onValueChange?.(value, eventDetails);
      }}
      {...props}
    />
  );
}

function AccordionItem({ className, ...props }: Skin<ComponentProps<typeof BaseAccordion.Item>>) {
  return <BaseAccordion.Item className={cx("echo-accordion__item", className)} {...props} />;
}

function Chevron() {
  return (
    <svg
      className="echo-accordion__chevron"
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      aria-hidden
    >
      <path d="M4 6l4 4 4-4" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function AccordionTrigger({
  className,
  children,
  ...props
}: Skin<ComponentProps<typeof BaseAccordion.Trigger>>) {
  return (
    <BaseAccordion.Header className="echo-accordion__header">
      <BaseAccordion.Trigger className={cx("echo-accordion__trigger", className)} {...props}>
        <span>{children}</span>
        <Chevron />
      </BaseAccordion.Trigger>
    </BaseAccordion.Header>
  );
}

function AccordionPanel({
  className,
  children,
  ...props
}: Skin<ComponentProps<typeof BaseAccordion.Panel>>) {
  return (
    <BaseAccordion.Panel className={cx("echo-accordion__panel", className)} {...props}>
      <div className="echo-accordion__panel-inner">{children}</div>
    </BaseAccordion.Panel>
  );
}

// Assembled into `Accordion` in index.ts, which isn't a client module (BUG-10).
export { AccordionRoot, AccordionItem, AccordionTrigger, AccordionPanel };

/**
 * The entry point for Accordion, deliberately NOT a client module: the parts are
 * attached here, from named client exports. Attached inside the "use client"
 * file, they didn't survive a server component's import, so Accordion.Item was
 * undefined in a Next.js page or layout and the build failed (BUG-10).
 */
import { AccordionRoot, AccordionItem, AccordionTrigger, AccordionPanel } from "./accordion";

export const Accordion = Object.assign(AccordionRoot, {
  Item: AccordionItem,
  Trigger: AccordionTrigger,
  Panel: AccordionPanel,
});
